#![allow(dead_code)]
mod baseline;
mod current;
mod spectrogram;
use std::f64::consts::PI;
fn tone(sr:u32,f:f64)->Vec<f64>{(0..sr).map(|i|(2.0*PI*f*i as f64/sr as f64).sin()).collect()}
fn rms(v:&[f64])->f64{let mid=&v[1100..9900];(mid.iter().map(|x|x*x).sum::<f64>()/mid.len() as f64).sqrt()}
fn main(){
 println!("input_rate_hz,old_4500_rms,new_4500_rms,old_5700_rms,new_5700_rms,old_5700_gain_db,new_5700_gain_db,old_constant_nonempty,new_constant_nonempty,constant_interior_frames");
 for sr in [16000,44100,48000,96000,192000]{
  let pass=tone(sr,4500.0);let stop=tone(sr,5700.0);
  let op=rms(&baseline::resample(&pass,sr as f64,11000.0));
  let np=rms(&current::resample(&pass,sr as f64,11000.0));
  let os=rms(&baseline::resample(&stop,sr as f64,11000.0));
  let ns=rms(&current::resample(&stop,sr as f64,11000.0));
  let constant=vec![0.1;sr as usize];
  let old=baseline::track_formants(&constant,sr,&baseline::FormantParams::default());
  let new=current::track_formants(&constant,sr,&current::FormantParams::default());
  let oldframes:Vec<_>=old.frames.iter().filter(|f|f.time_s>0.1&&f.time_s<0.9).collect();
  let newframes:Vec<_>=new.frames.iter().filter(|f|f.time_s>0.1&&f.time_s<0.9).collect();
  assert_eq!(oldframes.len(),newframes.len());
  let oldfalse=oldframes.iter().filter(|f|!f.formants_hz.is_empty()).count();
  let newfalse=newframes.iter().filter(|f|!f.formants_hz.is_empty()).count();
  println!("{sr},{op:.12},{np:.12},{os:.12},{ns:.12},{:.6},{:.6},{oldfalse},{newfalse},{}",20.0*(os*2.0_f64.sqrt()).log10(),20.0*(ns*2.0_f64.sqrt()).log10(),oldframes.len());
 }
}
